import { ChakraProvider, Box, Heading, Text } from "@chakra-ui/react";

export default function App() {
  return (
    <ChakraProvider>
      <Box p={6} borderRadius="md" bg="teal.50">
        <Heading size="lg">Hello, World!</Heading>
        <Text mt={2}>Premier composant Chakra UI.</Text>
      </Box>
    </ChakraProvider>
  );
}

